import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "" || raw == null) return null;
  if (raw.trim() !== "" && Number.isFinite(Number(raw))) return Number(raw);
  const upper = raw.toUpperCase();
  if (upper === "TRUE") return true;
  if (upper === "FALSE") return false;
  if (raw[0] === "'") return raw.slice(1);
  return raw;
}

// Parses every formula cell. Returns { nodes: Map addr -> { ast, refs } } (ast null when unparsable).
function parseAll(sheet) {
  const nodes = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (raw[0] !== "=") continue;
    try {
      const ast = parseFormula(raw.slice(1));
      nodes.set(addr, { ast, refs: refsOf(ast) });
    } catch {
      nodes.set(addr, { ast: null, refs: [] });
    }
  }
  return nodes;
}

// Iterative Tarjan over formula cells. Returns SCCs, each after the SCCs it reads, plus the set of cyclic cells.
function components(nodes) {
  const index = new Map(), low = new Map(), onStack = new Set();
  const stack = [], sccs = [], cyclic = new Set();
  let counter = 0;
  for (const root of nodes.keys()) {
    if (index.has(root)) continue;
    const work = [{ v: root, i: 0 }];
    index.set(root, counter); low.set(root, counter++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const { v } = frame;
      const refs = nodes.get(v).refs;
      if (frame.i < refs.length) {
        const w = refs[frame.i++];
        if (!nodes.has(w)) continue;
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++); stack.push(w); onStack.add(w);
          work.push({ v: w, i: 0 });
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) {
          const p = work[work.length - 1].v;
          low.set(p, Math.min(low.get(p), low.get(v)));
        }
        if (low.get(v) === index.get(v)) {
          const scc = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); scc.push(w); } while (w !== v);
          sccs.push(scc);
          if (scc.length > 1 || nodes.get(v).refs.includes(v)) for (const c of scc) cyclic.add(c);
        }
      }
    }
  }
  return { sccs, cyclic };
}

export function computeAll(sheet) {
  const values = new Map();
  const nodes = parseAll(sheet);
  for (const [addr, raw] of sheet.cells) if (!nodes.has(addr)) values.set(addr, valueOf(raw));
  const { sccs, cyclic } = components(nodes);
  const lookup = (a) => values.get(a) ?? null;
  for (const scc of sccs) {
    for (const addr of scc) {
      const { ast } = nodes.get(addr);
      if (cyclic.has(addr)) values.set(addr, "#CYCLE!");
      else values.set(addr, ast ? evaluate(ast, lookup) : "#ERROR!");
    }
  }
  return values;
}

const key = (addr) => { const a = parseAddr(addr); return a.row * 1048576 + a.col; };

export function dependents(sheet, addr) {
  const start = toAddr(parseAddr(addr).col, parseAddr(addr).row);
  const nodes = parseAll(sheet);
  const { cyclic } = components(nodes);
  const readers = new Map();
  for (const [a, { refs }] of nodes) for (const r of refs) {
    if (!readers.has(r)) readers.set(r, []);
    readers.get(r).push(a);
  }
  const found = new Set(), todo = [start];
  while (todo.length) for (const r of readers.get(todo.pop()) ?? []) {
    if (!found.has(r)) { found.add(r); todo.push(r); }
  }
  found.delete(start);
  for (const c of cyclic) found.delete(c);
  const pending = new Map(), heap = [];
  const push = (a) => {
    heap.push(a);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (key(heap[p]) <= key(heap[i])) break;
      [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && key(heap[c]) < key(heap[m])) m = c;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return top;
  };
  for (const a of found) {
    const n = new Set(nodes.get(a).refs.filter((r) => found.has(r))).size;
    pending.set(a, n);
    if (n === 0) push(a);
  }
  const out = [];
  while (heap.length) {
    const a = pop();
    out.push(a);
    for (const d of new Set(readers.get(a) ?? [])) {
      if (!found.has(d)) continue;
      const n = pending.get(d) - 1;
      pending.set(d, n);
      if (n === 0) push(d);
    }
  }
  return out;
}
