import { valueOf } from "./recalc.mjs";
import { parseAddr, toAddr, colIndex, colName } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";

function parseRange(range) {
  const [a, b] = range.split(":").map(parseAddr);
  return {
    c0: Math.min(a.col, b.col), c1: Math.max(a.col, b.col),
    r0: Math.min(a.row, b.row), r1: Math.max(a.row, b.row),
  };
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compareValues(x, y) {
  const rx = rank(x), ry = rank(y);
  if (rx !== ry) return rx - ry;
  if (rx === 0) return x - y;
  if (rx === 1) { const p = x.toLowerCase(), q = y.toLowerCase(); return p < q ? -1 : p > q ? 1 : 0; }
  return Number(x) - Number(y);
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c0, c1, r0, r1 } = parseRange(range);
  const start = options.header ? r0 + 1 : r0;
  const rows = [];
  for (let r = start; r <= r1; r++) {
    const raws = [];
    for (let c = c0; c <= c1; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push(raws);
  }
  const cols = keys.map((k) => ({ i: colIndex(k.col) - c0, desc: !!k.desc }));
  const vals = new Map(rows.map((row) => [row, cols.map(({ i }) => valueOf(row[i] ?? ""))]));
  rows.sort((p, q) => {
    const vp = vals.get(p), vq = vals.get(q);
    for (let k = 0; k < cols.length; k++) {
      const x = vp[k], y = vq[k];
      if (x === null || y === null) {
        if (x === y) continue;
        return x === null ? 1 : -1;
      }
      const d = compareValues(x, y);
      if (d) return cols[k].desc ? -d : d;
    }
    return 0;
  });
  rows.forEach((row, n) => row.forEach((raw, j) => setCell(sheet, toAddr(c0 + j, start + n), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c0, c1, r0, r1 } = parseRange(range);
  const find = (name) => {
    for (let c = c0; c <= c1; c++) if (String(values.get(toAddr(c, r0)) ?? "") === name) return c;
    throw new Error(`no such column: ${name}`);
  };
  const kc = find(rows), vc = find(value);
  const groups = new Map();
  for (let r = r0 + 1; r <= r1; r++) {
    const k = values.get(toAddr(kc, r)) ?? null;
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(values.get(toAddr(vc, r)) ?? null);
  }
  const aggregate = (list) => {
    if (agg === "count") return list.filter((v) => v !== null).length;
    const nums = list.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, v) => s + v, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, v) => s + v, 0) / nums.length;
    if (agg === "min") return nums.reduce((m, v) => (v < m ? v : m));
    if (agg === "max") return nums.reduce((m, v) => (v > m ? v : m));
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const keys = [...groups.keys()].filter((k) => k !== null).sort(compareValues);
  const out = keys.map((key) => ({ key, value: aggregate(groups.get(key)) }));
  if (groups.has(null)) out.push({ key: "(blank)", value: aggregate(groups.get(null)) });
  return out;
}
