// A subset of spreadsheet number formats. Numbers are handled as decimal digit strings, so rounding follows
// the way JavaScript prints the number.

// Splits a pattern on ";" outside quotes (and not after a backslash).
function splitSections(pattern) {
  const out = [];
  let cur = "", quoted = false;
  for (let i = 0; i < pattern.length; i++) {
    const ch = pattern[i];
    if (quoted) { cur += ch; if (ch === '"') quoted = false; }
    else if (ch === '"') { cur += ch; quoted = true; }
    else if (ch === "\\" && i + 1 < pattern.length) cur += ch + pattern[++i];
    else if (ch === ";") { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

function tokenize(section) {
  const toks = [];
  let seenPoint = false;
  for (let i = 0; i < section.length; i++) {
    const ch = section[i];
    if (ch === '"') {
      let j = section.indexOf('"', i + 1);
      if (j < 0) j = section.length;
      toks.push({ t: "lit", s: section.slice(i + 1, j) });
      i = j;
    } else if (ch === "\\") {
      if (i + 1 < section.length) toks.push({ t: "lit", s: section[++i] });
    } else if (ch === "0" || ch === "#") toks.push({ t: "digit", ch, post: seenPoint });
    else if (ch === "." && !seenPoint) { seenPoint = true; toks.push({ t: "point" }); }
    else if (ch === ",") toks.push({ t: "comma" });
    else if (ch === "%") toks.push({ t: "pct" });
    else if ((ch === "E" || ch === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      const plus = section[i + 1] === "+";
      let n = 0;
      i += 2;
      while (section[i] === "0") { n++; i++; }
      i--;
      toks.push({ t: "exp", plus, n });
    } else toks.push({ t: "lit", s: ch });
  }
  return toks;
}

// Decimal digits of a non-negative number as JavaScript prints it: { int, frac }.
function decimal(abs) {
  const s = String(abs);
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(s);
  let int = m[1], frac = m[2] ?? "";
  const e = Number(m[3] ?? 0);
  return shift({ int, frac }, e);
}

// Multiplies by 10^n.
function shift({ int, frac }, n) {
  if (n > 0) {
    frac = frac.padEnd(n, "0");
    int += frac.slice(0, n);
    frac = frac.slice(n);
  } else if (n < 0) {
    int = int.padStart(-n + 1, "0");
    frac = int.slice(int.length + n) + frac;
    int = int.slice(0, int.length + n);
  }
  return { int: int.replace(/^0+(?=\d)/, ""), frac };
}

// Rounds half away from zero to d decimals.
function round({ int, frac }, d) {
  const up = frac.length > d && frac[d] >= "5";
  let n = (BigInt(int + frac.slice(0, d)) + (up ? 1n : 0n)).toString().padStart(d + 1, "0");
  return { int: n.slice(0, n.length - d), frac: n.slice(n.length - d) };
}

export function formatNumber(value, pattern) {
  if (value == null) return "";
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (typeof value !== "number") return String(value);
  if (pattern === "General" || !Number.isFinite(value)) return String(value);

  const sections = splitSections(pattern);
  let idx = 0, ownSign = false;
  if (sections.length >= 2 && value < 0) { idx = 1; ownSign = true; }
  else if (sections.length >= 3 && value === 0) idx = 2;
  const section = sections[idx];
  if (section === "General") return String(value);
  const toks = tokenize(section);

  let dec = decimal(Math.abs(value));
  if (toks.some((t) => t.t === "pct")) dec = shift(dec, 2);

  const exp = toks.find((t) => t.t === "exp");
  const pointAt = toks.findIndex((t) => t.t === "point");
  const preDigits = toks.filter((t) => t.t === "digit" && !t.post);
  const postDigits = toks.filter((t) => t.t === "digit" && t.post);
  const decimals = postDigits.length;
  const minFrac = postDigits.lastIndexOf(postDigits.findLast((t) => t.ch === "0")) + 1;

  let e = 0, num;
  if (exp) {
    const all = dec.int + dec.frac;
    const first = all.search(/[1-9]/);
    let digits = "0";
    if (first >= 0) { e = dec.int.length - 1 - first; digits = all.slice(first); }
    num = round({ int: digits[0], frac: digits.slice(1) }, decimals);
    if (num.int.length > 1) { e++; num = { int: "1", frac: "0".repeat(decimals) }; }
  } else num = round(dec, decimals);

  const isZero = /^0*$/.test(num.int + num.frac);
  let intStr = num.int.replace(/^0+/, "");
  const minInt = exp ? 1 : preDigits.filter((t) => t.ch === "0").length;
  intStr = intStr.padStart(minInt, "0");
  const firstD = toks.findIndex((t) => t.t === "digit" && !t.post);
  const lastD = toks.findLastIndex((t) => t.t === "digit" && !t.post);
  if (toks.slice(firstD, lastD + 1).some((t) => t.t === "comma") && firstD >= 0) {
    intStr = intStr.replace(/\B(?=(\d{3})+$)/g, ",");
  }
  let fracStr = num.frac;
  while (fracStr.length > minFrac && fracStr.endsWith("0")) fracStr = fracStr.slice(0, -1);

  let out = "", intDone = false;
  for (const t of toks) {
    if (t.t === "lit") out += t.s;
    else if (t.t === "digit" && !t.post) { if (!intDone) { out += intStr; intDone = true; } }
    else if (t.t === "point") out += "." + fracStr;
    else if (t.t === "pct") out += "%";
    else if (t.t === "exp") {
      out += "E" + (e < 0 ? "-" : t.plus ? "+" : "") + String(Math.abs(e)).padStart(t.n, "0");
    }
  }
  return value < 0 && !ownSign && !isZero ? "-" + out : out;
}
