  const delim = options.delimiter ?? detectDelimiter(text);
  const sheet = createSheet();
  let row = 0, col = 0, field = "", started = false, line = 1;
  const endField = () => {
    if (field.startsWith("=") && !options.formulas) field = "'" + field;
    setCell(sheet, toAddr(col, row), field);
    field = "";
    col++;
  };
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"' && field === "" && (i === 0 || text[i - 1] === delim || text[i - 1] === "\n")) {
      const startLine = line;
      started = true;
      let j = i + 1;
      for (;; j++) {
        if (j >= text.length) throw new Error(`unclosed quote at line ${startLine}`);
        if (text[j] === '"') {
          if (text[j + 1] === '"') { field += '"'; j++; } else break;
        } else { if (text[j] === "\n") line++; field += text[j]; }
      }
      i = j;
      // Keep the field marked non-bare so a following quote is literal text.
      if (field === "") field = "";
    } else if (ch === delim) { started = true; endField(); }
    else if (ch === "\n" || (ch === "\r" && text[i + 1] === "\n")) {
      if (ch === "\r") i++;
      endField();
      row++; col = 0; started = false; line++;
    } else { started = true; field += ch; }
  }
  if (started) endField();
  return sheet;
}
