// Row and column insertion/deletion, rewriting every formula's references to follow the moved cells.
import { parseAddr, toAddr, colName, colIndex } from "./addr.mjs";

const REF = String.raw`\$?[A-Za-z]{1,3}\$?[1-9]\d*`;
const TOKEN = new RegExp(String.raw`"(?:[^"]|"")*"?|(?<![A-Za-z0-9_.])(${REF})(?::(${REF}))?(?![A-Za-z0-9_.(])`, "g");
const PART = /^(\$?)([A-Za-z]+)(\$?)(\d+)$/;

// shift(i) maps an index to its new index; for deletions it returns null for removed ones.
// Ends of a range are mapped with `lo`/`hi` rules instead, see rewriteRange.
function rewritePart(text, axis, idx) {
  const m = PART.exec(text);
  if (idx === parseAddr(text.replace(/\$/g, "")).row && axis === "row") return text;
  if (idx === colIndex(m[2]) && axis === "col") return text;
  return axis === "row" ? `${m[1]}${m[2]}${m[3]}${idx + 1}` : `${m[1]}${colName(idx)}${m[3]}${m[4]}`;
}

const indexOf = (text, axis) => {
  const m = PART.exec(text);
  return axis === "row" ? Number(m[4]) - 1 : colIndex(m[2]);
};

function rewriteFormula(raw, axis, at, count, del) {
  return raw.replace(TOKEN, (tok, a, b) => {
    if (!a) return tok;
    const ia = indexOf(a, axis);
    if (!b) {
      let n;
      if (!del) n = ia >= at ? ia + count : ia;
      else if (ia >= at + count) n = ia - count;
      else if (ia >= at) return "#REF!";
      else n = ia;
      return rewritePart(a, axis, n);
    }
    const ib = indexOf(b, axis);
    const lo = Math.min(ia, ib), hi = Math.max(ia, ib);
    let nlo, nhi;
    if (!del) {
      nlo = lo >= at ? lo + count : lo;
      nhi = hi >= at ? hi + count : hi;
    } else {
      nlo = lo < at ? lo : lo >= at + count ? lo - count : at;
      nhi = hi < at ? hi : hi >= at + count ? hi - count : at - 1;
      if (nlo > nhi) return "#REF!";
    }
    const [na, nb] = ia <= ib ? [nlo, nhi] : [nhi, nlo];
    return `${rewritePart(a, axis, na)}:${rewritePart(b, axis, nb)}`;
  });
}

function restructure(sheet, axis, at, count, del) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const p = parseAddr(addr);
    let i = axis === "row" ? p.row : p.col;
    if (del) {
      if (i >= at && i < at + count) continue;
      if (i >= at + count) i -= count;
    } else if (i >= at) i += count;
    const key = axis === "row" ? toAddr(p.col, i) : toAddr(i, p.row);
    next.set(key, raw.startsWith("=") ? "=" + rewriteFormula(raw.slice(1), axis, at, count, del) : raw);
  }
  sheet.cells = next;
}

const rowAt = (at) => {
  if (!Number.isInteger(at) || at < 1) throw new Error(`bad row: ${at}`);
  return at - 1;
};
const colAt = (at) => {
  if (!/^[A-Za-z]{1,3}$/.test(at)) throw new Error(`bad column: ${at}`);
  return colIndex(at);
};

export const insertRows = (sheet, at, count = 1) => restructure(sheet, "row", rowAt(at), count, false);
export const deleteRows = (sheet, at, count = 1) => restructure(sheet, "row", rowAt(at), count, true);
export const insertCols = (sheet, at, count = 1) => restructure(sheet, "col", colAt(at), count, false);
export const deleteCols = (sheet, at, count = 1) => restructure(sheet, "col", colAt(at), count, true);
